scripts.analyze.py:
"""JRD3 analysis: QR2/QR4 assembly, verification, fits, QR3 and QR0 readings.
Reads only this task's scratch (runs/, qr1.json). Writes analysis.json."""
import json
import math
import os
import sys

S = sys.argv[1]
R = os.path.join(S, "runs")
FAMS = ["E-INT", "E-DEC", "E-NP"]
DEGS = ["2^20", "2^22", "5^10", "2^24", "5^11", "6^10", "3^17"]
SMALL = ["2^4", "2^8", "2^12", "2^16"]
SEC_PER_DAY = 86400.0
LIMIT_BITS = 2 ** 36


def dexpr(s):
    b, _, e = s.partition("^")
    return int(b) ** int(e) if e else int(b)


def tag(s):
    return s.replace("^", "p")


def load_item(item_id):
    d = os.path.join(R, item_id)
    if not os.path.isdir(d):
        return None
    rec = {"id": item_id}
    for name in ("cmd.txt", "pre.txt", "post.txt", "time.txt", "rc.txt", "err.txt"):
        p = os.path.join(d, name)
        rec[name] = open(p).read() if os.path.exists(p) else None
    lines = []
    p = os.path.join(d, "out.jsonl")
    if os.path.exists(p):
        for ln in open(p):
            ln = ln.strip()
            if ln:
                try:
                    lines.append(json.loads(ln))
                except ValueError:
                    lines.append({"phase": "unparseable", "raw": ln})
    rec["phases"] = lines
    rc = rec["rc.txt"]
    rec["rc"] = int(rc.strip()) if rc else None
    return rec


HOST2_FROM = "2026-10-09T02:00:00Z"   # second container restart; CPU model changed


def host_of(rec):
    """H1 = Intel Xeon @ 2.80GHz (all items started before the second restart);
    H2 = Intel Xeon @ 2.10GHz (items started after it). From pre.txt start time."""
    if rec is None or not rec.get("pre.txt"):
        return None
    t = rec["pre.txt"].split("\n")[0].strip()
    return "H2" if t >= HOST2_FROM else "H1"


def phase(rec, name):
    for p in rec["phases"]:
        if p.get("phase") == name:
            return p
    return None


def outcome(rec, main_phase):
    if rec is None:
        return "not_run"
    if rec["rc"] is None:
        return "running_or_interrupted"
    p = phase(rec, main_phase)
    if rec["rc"] == 0 and p is not None:
        return "completed"
    if rec["rc"] == 124:
        return "watchdog_expiry" if p is None else "completed_then_watchdog"
    if phase(rec, "error") is not None and phase(rec, "error").get("error") == "MemoryError":
        return "MemoryError"
    err = (rec.get("err.txt") or "")
    if "MemoryError" in err or "Unable to allocate" in err:
        return "MemoryError"
    return f"failed_rc_{rec['rc']}"


def rss_kib(p):
    return p["status"]["ru_maxrss_kib"] if p and "status" in p else None


def first_existing(*ids):
    for i in ids:
        r = load_item(i)
        if r is not None:
            return r, i
    return None, ids[0]


# ------------------------------------------------------------------ QR2
qr2 = {"product": {}, "modsq": {}, "mu": {}}
prod_hash = {}   # D -> list of (family, variant, sha_c, sha_a, sha_b)
msq_hash = {}
mu_hash = {}
for F in FAMS:
    for Ds in DEGS:
        D = dexpr(Ds)
        stage = "B" if F == "E-INT" and Ds in ("2^20", "2^22", "5^10", "2^24") else (
            "C" if F == "E-INT" else "A")
        for kind, main in (("prod", "product"), ("msq", "msq")):
            rec = load_item(f"{stage}-{kind}-{F}-{tag(Ds)}")
            oc = outcome(rec, main)
            p = phase(rec, main) if rec else None
            entry = {"family": F, "D_expr": Ds, "D": D, "item": f"{stage}-{kind}-{F}-{tag(Ds)}",
                     "outcome": oc, "rc": rec["rc"] if rec else None, "host": host_of(rec),
                     "bash_time": rec["time.txt"].strip() if rec and rec["time.txt"] else None}
            if p:
                entry["seconds"] = p["seconds"]
                entry["peak_rss_kib"] = rss_kib(p)
                entry["VmHWM"] = p["status"].get("VmHWM")
                entry["VmPeak"] = p["status"].get("VmPeak")
                entry["loadavg_before"] = p.get("loadavg_before")
                entry["loadavg_after"] = p.get("loadavg_after")
                entry["baseline_rss_kib"] = rss_kib(phase(rec, "header"))
                if kind == "prod":
                    entry["sha_c"] = p["sha_c"]
                    entry["deg_c"] = p["deg_c"]
                    if p.get("enp"):
                        entry["enp_N"] = p["enp"]["N"]
                        entry["enp_max_residual"] = p["enp"]["max_residual"]
                    g = phase(rec, "generated")
                    prod_hash.setdefault(D, []).append(
                        (F, "unsplit", p["sha_c"], g["sha_a"], g["sha_b"]))
                else:
                    for k in ("seconds_square", "seconds_quotient", "seconds_qm",
                              "deg_r", "deg_r_below_D", "deg_q", "sha_r", "sha_q"):
                        entry[k] = p[k]
                    if p.get("enp"):
                        entry["enp_N_last"] = p["enp"]["N"]
                        entry["enp_max_residual_last"] = p["enp"]["max_residual"]
                    g = phase(rec, "loaded")
                    msq_hash.setdefault(D, []).append(
                        (F, "unsplit", p["sha_r"], p["sha_q"], g["sha_m"], g["sha_a"],
                         p["deg_r_below_D"]))
            if rec and oc != "completed":
                err = phase(rec, "error")
                entry["error_detail"] = err.get("detail") if err else (rec.get("err.txt") or "")[-500:]
            # split variant, if run
            srec = load_item(f"{stage}-{kind}-{F}-{tag(Ds)}-split")
            if srec is not None:
                sp = phase(srec, main)
                se = {"outcome": outcome(srec, main), "rc": srec["rc"],
                      "item": f"{stage}-{kind}-{F}-{tag(Ds)}-split",
                      "bash_time": srec["time.txt"].strip() if srec["time.txt"] else None}
                if sp:
                    se["seconds"] = sp["seconds"]
                    se["peak_rss_kib"] = rss_kib(sp)
                    se["baseline_rss_kib"] = rss_kib(phase(srec, "header"))
                    if kind == "prod":
                        se["sha_c"] = sp["sha_c"]
                        g = phase(srec, "generated")
                        prod_hash.setdefault(D, []).append(
                            (F, "split", sp["sha_c"], g["sha_a"], g["sha_b"]))
                    else:
                        se["sha_r"] = sp["sha_r"]
                        se["sha_q"] = sp["sha_q"]
                        se["deg_r_below_D"] = sp["deg_r_below_D"]
                        g = phase(srec, "loaded")
                        msq_hash.setdefault(D, []).append(
                            (F, "split", sp["sha_r"], sp["sha_q"], g["sha_m"], g["sha_a"],
                             sp["deg_r_below_D"]))
                entry["split_variant"] = se
            qr2["product" if kind == "prod" else "modsq"][f"{F}|{Ds}"] = entry

# mu precomputation (E-NP all degrees incl. small, E-DEC QR2 degrees, E-INT where run)
for F, degs, stage in (("E-NP", DEGS + SMALL, "A"), ("E-DEC", DEGS, "A"),
                       ("E-INT", ["2^20", "2^22"], "B")):
    for Ds in degs:
        rec = load_item(f"{stage}-mu-{F}-{tag(Ds)}")
        oc = outcome(rec, "mu")
        p = phase(rec, "mu") if rec else None
        e = {"family": F, "D_expr": Ds, "outcome": oc}
        if p:
            e.update(seconds=p["seconds"], peak_rss_kib=rss_kib(p), sha_mu=p["sha_mu"],
                     deg_mu=p["deg_mu"], sha_m=p["sha_m"])
            mu_hash.setdefault(dexpr(Ds), []).append((F, p["sha_mu"], p["sha_m"]))
        qr2["mu"][f"{F}|{Ds}"] = e

# verification by a second family (identical operands, SHA-256 of result)
verif = {"product": {}, "modsq": {}, "mu": {}}
for D, lst in prod_hash.items():
    for (F, var, h, ha, hb) in lst:
        others = [(F2, v2) for (F2, v2, h2, ha2, hb2) in lst
                  if F2 != F and h2 == h and ha2 == ha and hb2 == hb]
        disagree = [(F2, v2) for (F2, v2, h2, ha2, hb2) in lst
                    if F2 != F and h2 != h and ha2 == ha and hb2 == hb]
        verif["product"][f"{F}|{var}|{D}"] = {"agrees_with": others, "disagrees_with": disagree,
                                              "verified": bool(others) and not disagree}
for D, lst in msq_hash.items():
    for (F, var, hr, hq, hm, ha, degok) in lst:
        others = [(F2, v2) for (F2, v2, hr2, hq2, hm2, ha2, _) in lst
                  if F2 != F and hr2 == hr and hq2 == hq and hm2 == hm and ha2 == ha]
        disagree = [(F2, v2) for (F2, v2, hr2, hq2, hm2, ha2, _) in lst
                    if F2 != F and (hr2 != hr or hq2 != hq) and hm2 == hm and ha2 == ha]
        verif["modsq"][f"{F}|{var}|{D}"] = {"deg_r_below_D": degok, "agrees_with": others,
                                            "disagrees_with": disagree,
                                            "verified": bool(degok and others and not disagree)}
for D, lst in mu_hash.items():
    hs = {h for (_, h, _) in lst}
    fams = [F for (F, _, _) in lst]
    verif["mu"][str(D)] = {"families": fams, "all_equal": len(hs) == 1,
                           "verified_by_second_family": len(set(fams)) >= 2 and len(hs) == 1}

for kind in ("product", "modsq"):
    for key, e in qr2[kind].items():
        if e.get("outcome") == "completed":
            v = verif[kind].get(f"{e['family']}|unsplit|{e['D']}")
            e["verification"] = v
        sv = e.get("split_variant")
        if sv and sv.get("outcome") == "completed":
            sv["verification"] = verif[kind].get(f"{e['family']}|split|{e['D']}")

# ------------------------------------------------------------------ gcd
def lsq(xs, ys):
    n = len(xs)
    mx, my = sum(xs) / n, sum(ys) / n
    sxx = sum((x - mx) ** 2 for x in xs)
    sxy = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    a = sxy / sxx
    b = my - a * mx
    ss_res = sum((y - (a * x + b)) ** 2 for x, y in zip(xs, ys))
    ss_tot = sum((y - my) ** 2 for y in ys)
    return a, b, 1 - ss_res / ss_tot if ss_tot > 0 else None


gcd = []
for k in range(16, 31):
    rec = load_item(f"A-gcd-2p{k}") or load_item(f"B-gcd-2p{k}")
    if rec is None:
        continue
    oc = outcome(rec, "gcd")
    p = phase(rec, "gcd")
    e = {"D_expr": f"2^{k}", "D": 2 ** k, "item": rec["id"], "outcome": oc, "rc": rec["rc"],
         "host": host_of(rec),
         "bash_time": rec["time.txt"].strip() if rec["time.txt"] else None}
    if p:
        e.update(seconds=p["seconds"], peak_rss_kib=rss_kib(p), deg_g=p["deg_g"],
                 baseline_rss_kib=rss_kib(phase(rec, "header")),
                 sha_g=p["sha_g"], loadavg_before=p["loadavg_before"],
                 loadavg_after=p["loadavg_after"])
        dv = phase(rec, "divisibility")
        if dv:
            e["g_divides_a_and_b"] = dv["g_divides_a"] and dv["g_divides_b"]
        vrec = load_item(f"A-gcdv-2p{k}") or load_item(f"D-gcdv-2p{k}")
        if vrec is not None and phase(vrec, "gcdv"):
            vp = phase(vrec, "gcdv")
            e["stein_check"] = {"item": vrec["id"], "sha_g": vp["sha_g"],
                                "equal": vp["sha_g"] == p["sha_g"],
                                "stein_seconds": vp["seconds"]}
    gcd.append(e)
gcd_done = [e for e in gcd if e["outcome"] == "completed"]
gfit = None
if len(gcd_done) >= 2:
    xs = [math.log2(e["D"]) for e in gcd_done]
    ys = [math.log2(e["seconds"]) for e in gcd_done]
    a, b, r2 = lsq(xs, ys)
    gfit = {"model": "seconds = 2^b * D^a, least squares on (log2 D, log2 seconds)",
            "points": [e["D_expr"] for e in gcd_done], "a_exponent": a, "b_log2_const": b,
            "c_seconds": 2 ** b, "R2": r2}
    top = gcd_done[-3:]
    if len(top) >= 2:
        a3, b3, r23 = lsq([math.log2(e["D"]) for e in top], [math.log2(e["seconds"]) for e in top])
        gfit["alt_top3"] = {"points": [e["D_expr"] for e in top], "a_exponent": a3,
                            "b_log2_const": b3, "R2": r23}

sup_gcd = {}
for Ds in ("2^4", "2^8", "2^12"):
    rec = load_item(f"A-sup-gcd-{tag(Ds)}")
    p = phase(rec, "gcd") if rec else None
    sup_gcd[Ds] = {"outcome": outcome(rec, "gcd"), "seconds": p["seconds"] if p else None,
                   "peak_rss_kib": rss_kib(p) if p else None}
sup_msq = {}
for F in FAMS:
    for Ds in SMALL:
        rec = load_item(f"A-sup-msq-{F}-{tag(Ds)}")
        p = phase(rec, "msq") if rec else None
        sup_msq[f"{F}|{Ds}"] = {"outcome": outcome(rec, "msq"),
                                "seconds": p["seconds"] if p else None,
                                "peak_rss_kib": rss_kib(p) if p else None,
                                "deg_r_below_D": p["deg_r_below_D"] if p else None,
                                "sha_r": p["sha_r"] if p else None}
for Ds in SMALL:
    hs = {sup_msq[f"{F}|{Ds}"]["sha_r"] for F in FAMS if sup_msq[f"{F}|{Ds}"]["sha_r"]}
    for F in FAMS:
        sup_msq[f"{F}|{Ds}"]["all_families_agree"] = (len(hs) == 1)

# ------------------------------------------------------------------ QR4
qr4 = []
for k in range(8, 15):
    rec = load_item(f"A-ge-2p{k}")
    oc = outcome(rec, "ge")
    p = phase(rec, "ge") if rec else None
    e = {"m": 2 ** k, "m_expr": f"2^{k}", "outcome": oc, "host": host_of(rec),
         "bash_time": rec["time.txt"].strip() if rec and rec["time.txt"] else None}
    if p:
        e.update(seconds=p["seconds"], peak_rss_kib=rss_kib(p), rank=p["rank"],
                 echelon_check=p["echelon_check"], loadavg_before=p["loadavg_before"],
                 loadavg_after=p["loadavg_after"])
    qr4.append(e)

# ------------------------------------------------------------------ QR3
qr1 = json.load(open(os.path.join(S, "qr1.json")))


def family_points(F, include_small=False, use_split_fallback=False):
    pts = []
    for Ds in DEGS:
        e = qr2["modsq"].get(f"{F}|{Ds}")
        if e and e["outcome"] == "completed":
            pts.append((e["D"], e["seconds"], e["peak_rss_kib"], "unsplit", e["baseline_rss_kib"]))
        elif use_split_fallback and e and e.get("split_variant", {}).get("outcome") == "completed":
            sv = e["split_variant"]
            pts.append((e["D"], sv["seconds"], sv["peak_rss_kib"], "split", sv["baseline_rss_kib"]))
    if include_small:
        for Ds in SMALL:
            e = sup_msq.get(f"{F}|{Ds}")
            if e and e["outcome"] == "completed":
                pts.append((dexpr(Ds), e["seconds"], e["peak_rss_kib"], "supplementary", 0))
    pts.sort()
    return pts


def fit_points(pts):
    if len(pts) < 2:
        return None
    a, b, r2 = lsq([math.log2(p[0]) for p in pts], [math.log2(p[1]) for p in pts])
    return {"a_exponent": a, "b_log2_const": b, "R2": r2, "points": [p[0] for p in pts]}


def t_sq(B, pts, fit, extrap="fit"):
    """log-log piecewise-linear interpolation; outside: power-law fit (or the
    end segment extended, extrap='segment')."""
    if not pts:
        return None, "no_measurement"
    lB = math.log2(B)
    xs = [math.log2(p[0]) for p in pts]
    ys = [math.log2(p[1]) for p in pts]
    for x, y in zip(xs, ys):
        if x == lB:
            return 2 ** y, "measured"
    if xs[0] < lB < xs[-1]:
        for i in range(len(xs) - 1):
            if xs[i] < lB < xs[i + 1]:
                y = ys[i] + (ys[i + 1] - ys[i]) * (lB - xs[i]) / (xs[i + 1] - xs[i])
                return 2 ** y, "interpolated"
    if extrap == "segment" and len(xs) >= 2:
        if lB > xs[-1]:
            i, j = -2, -1
        else:
            i, j = 0, 1
        sl = (ys[j] - ys[i]) / (xs[j] - xs[i])
        return 2 ** (ys[j] + sl * (lB - xs[j])), "extrapolated_end_segment"
    return 2 ** (fit["b_log2_const"] + fit["a_exponent"] * lB), (
        "extrapolated_fit_above" if lB > xs[-1] else "extrapolated_fit_below")


def t_gcd(B, fit):
    return 2 ** (fit["b_log2_const"] + fit["a_exponent"] * math.log2(B))


def item_status_at(kind_key, F, B, use_split=False):
    for Ds in DEGS:
        if dexpr(Ds) == B:
            e = qr2[kind_key].get(f"{F}|{Ds}")
            if not e:
                return "not_run"
            sv = e.get("split_variant")
            if use_split and e["outcome"] != "completed" and sv and sv.get("outcome") == "completed":
                return "completed"
            return e["outcome"]
    if kind_key == "modsq":
        for Ds in SMALL:
            if dexpr(Ds) == B:
                e = sup_msq.get(f"{F}|{Ds}")
                return e["outcome"] if e else "not_run"
    return None


def gcd_status_at(B):
    for e in gcd:
        if e["D"] == B:
            return e["outcome"]
    for Ds, e in sup_gcd.items():
        if dexpr(Ds) == B:
            return e["outcome"]
    return None


def largest_attempted(F):
    best = None
    for Ds in DEGS:
        e = qr2["modsq"].get(f"{F}|{Ds}")
        if e and e["outcome"] != "not_run":
            best = max(best or 0, e["D"])
    return best


def mem_verdict(B, F, pts, nonmem_counts_as_fail, minus_baseline=False,
                per_input_bit=False, largest_rule="completed", use_split=False):
    """Returns (verdict, reasons)."""
    reasons = []
    fail_set = {"MemoryError"} | ({"watchdog_expiry"} if nonmem_counts_as_fail else set())
    st = item_status_at("modsq", F, B, use_split)
    if st is not None and (st in fail_set or (nonmem_counts_as_fail and st.startswith("failed"))):
        reasons.append(f"modsq at B on {F}: {st}")
    gs = gcd_status_at(B)
    if gs is not None and (gs in fail_set or (nonmem_counts_as_fail and gs.startswith("failed"))):
        reasons.append(f"gcd at B: {gs}")
    # above largest measured degree: linear extrapolation of peak RSS per bit
    if pts:
        Dmax, _, rss, _, base = max(pts)
        lim = Dmax
        if largest_rule == "attempted":
            lim = max(Dmax, largest_attempted(F) or 0)
        if B > lim:
            per_bit = (rss - (base if minus_baseline else 0)) * 1024 * 8 / Dmax
            if per_input_bit:
                per_bit /= 2
            est = max(2 * B, per_bit * B)
            if est > LIMIT_BITS:
                reasons.append(f"modsq extrapolated memory max(2B, {per_bit:.1f} bits/bit x B)"
                               f" = 2^{math.log2(est):.2f} bits > 2^36")
    if gcd_done:
        g = max(gcd_done, key=lambda e: e["D"])
        if B > g["D"]:
            per_bit = (g["peak_rss_kib"] - (g["baseline_rss_kib"] if minus_baseline else 0)) * 1024 * 8 / g["D"]
            if per_input_bit:
                per_bit /= 2
            est = max(2 * B, per_bit * B)
            if est > LIMIT_BITS:
                reasons.append(f"gcd extrapolated memory max(2B, {per_bit:.1f} bits/bit x B)"
                               f" = 2^{math.log2(est):.2f} bits > 2^36")
    return ("FAIL" if reasons else "PASS"), reasons


def qr3_table(include_small=False, extrap="fit", nonmem_counts_as_fail=False,
              smallest_mem_rule="all_fail", gfit_use=None, use_split_fallback=False,
              minus_baseline=False, per_input_bit=False, largest_rule="completed",
              gcd_measured_on_ladder=False, smallest_excludes_failed_at_B=False):
    gf = gfit_use or gfit
    PTS = {F: family_points(F, include_small, use_split_fallback) for F in FAMS}
    FITS = {F: fit_points(PTS[F]) for F in FAMS}
    rows = []
    for row in qr1["rows"]:
        B = int(row["B"])
        G = row["G"]
        tg = t_gcd(B, gf)
        if gcd_measured_on_ladder:
            for e in gcd_done:
                if e["D"] == B:
                    tg = e["seconds"]
        out = {"cell": row["cell"], "d": row["d"], "B": row["B"], "log2B": row["log2B_2dp"],
               "G": G, "t_gcd_s": tg, "columns": {}}
        tsq_by = {}
        mv_by = {}
        failed_at_B = {}
        for F in FAMS:
            ts, how = t_sq(B, PTS[F], FITS[F], extrap)
            st_B = item_status_at("modsq", F, B, use_split_fallback)
            if st_B is not None and st_B != "completed":
                how = how + "; item at B " + st_B
                failed_at_B[F] = st_B
            tsq_by[F] = ts
            TA = G * (131 * ts + tg) / SEC_PER_DAY if ts is not None else None
            M, reasons = mem_verdict(B, F, PTS[F], nonmem_counts_as_fail, minus_baseline,
                                     per_input_bit, largest_rule, use_split_fallback)
            mv_by[F] = (M, reasons)
            route = "X" if (M == "FAIL" or (TA is not None and TA > 90)) else "D"
            out["columns"][F] = {"t_sq_s": ts, "t_sq_basis": how, "T_A_days": TA, "M": M,
                                 "M_reasons": reasons, "route": route,
                                 "marginal": (TA is not None and 30 < TA <= 270)}
        avail = {F: v for F, v in tsq_by.items() if v is not None
                 and not (smallest_excludes_failed_at_B and F in failed_at_B)}
        Fmin = min(avail, key=avail.get)
        ts = avail[Fmin]
        TA = G * (131 * ts + tg) / SEC_PER_DAY
        if smallest_mem_rule == "all_fail":
            M = "FAIL" if all(mv_by[F][0] == "FAIL" for F in FAMS) else "PASS"
            reasons = {F: mv_by[F][1] for F in FAMS} if M == "FAIL" else {}
        else:  # the family attaining the minimum
            M, reasons = mv_by[Fmin]
        route = "X" if (M == "FAIL" or TA > 90) else "D"
        out["columns"]["smallest"] = {"t_sq_s": ts, "t_sq_family": Fmin, "T_A_days": TA,
                                      "M": M, "M_reasons": reasons, "route": route,
                                      "marginal": 30 < TA <= 270}
        rows.append(out)
    return {"fits": FITS, "points": {F: PTS[F] for F in FAMS}, "rows": rows}


host_control = []
for hid, ref_kind, ref_key, main in (
        ("H-prod-E-INT-2p20", "product", "E-INT|2^20", "product"),
        ("H-msq-E-INT-2p20", "modsq", "E-INT|2^20", "msq"),
        ("H-prod-E-INT-2p22", "product", "E-INT|2^22", "product"),
        ("H-prod-E-DEC-2p24", "product", "E-DEC|2^24", "product"),
        ("H-prod-E-NP-2p24", "product", "E-NP|2^24", "product"),
        ("H-gcd-2p20", "gcd", "2^20", "gcd")):
    rec = load_item(hid)
    oc = outcome(rec, main)
    p = phase(rec, main) if rec else None
    if ref_kind == "gcd":
        ref = next((e for e in gcd if e["D_expr"] == ref_key), None)
    else:
        ref = qr2[ref_kind].get(ref_key)
    h = {"item": hid, "host": host_of(rec), "outcome": oc,
         "seconds_H2": p["seconds"] if p else None,
         "seconds_H1": ref.get("seconds") if ref else None,
         "reference_item": ref.get("item") if ref else None}
    if p:
        h["peak_rss_kib_H2"] = rss_kib(p)
        same = None
        for k in ("sha_c", "sha_r", "sha_g"):
            if k in p and ref and (ref.get(k) is not None):
                same = (p[k] == ref[k])
        h["same_result_as_H1"] = same
    if h["seconds_H1"] and h["seconds_H2"]:
        h["ratio_H2_over_H1"] = h["seconds_H2"] / h["seconds_H1"]
    host_control.append(h)

result = {"qr2": qr2, "host_control": host_control, "verification": verif, "gcd": gcd, "gcd_fit": gfit,
          "supplementary_msq": sup_msq, "supplementary_gcd": sup_gcd, "qr4": qr4}
if gfit and any(family_points(F) for F in FAMS):
    result["qr3_primary"] = qr3_table()
    alts = {
        "A1_include_supplementary_small_degrees": dict(include_small=True),
        "A2_extrapolate_by_end_segment": dict(extrap="segment"),
        "A3_watchdog_expiry_counts_as_not_completed": dict(nonmem_counts_as_fail=True),
        "A4_smallest_column_memory_from_min_family": dict(smallest_mem_rule="min_family"),
        "A5_split_variant_where_unsplit_failed": dict(use_split_fallback=True),
        "A7_rss_per_bit_minus_interpreter_baseline": dict(minus_baseline=True),
        "A8_rss_per_input_bit_two_operands": dict(per_input_bit=True),
        "A9_largest_measured_degree_read_as_largest_attempted": dict(largest_rule="attempted"),
        "A10_gcd_measured_value_where_B_on_ladder": dict(gcd_measured_on_ladder=True),
        "A11_smallest_excludes_family_not_completed_at_B": dict(smallest_excludes_failed_at_B=True),
    }
    if gfit.get("alt_top3"):
        alts["A6_gcd_fit_top3_points"] = dict(gfit_use=gfit["alt_top3"])
    result["qr3_alternatives"] = {}
    prim = result["qr3_primary"]["rows"]
    for name, kw in alts.items():
        tab = qr3_table(**kw)
        diffs = []
        for r0, r1 in zip(prim, tab["rows"]):
            for col in FAMS + ["smallest"]:
                c0, c1 = r0["columns"][col], r1["columns"][col]
                changed = [k for k in ("M", "route", "marginal") if c0[k] != c1[k]]
                rel = None
                if c0["T_A_days"] and c1["T_A_days"]:
                    rel = c1["T_A_days"] / c0["T_A_days"]
                if changed or (rel is not None and abs(rel - 1) > 1e-9):
                    diffs.append({"cell": r0["cell"], "d": r0["d"], "column": col,
                                  "changed": changed, "T_A_ratio_alt_over_primary": rel,
                                  "alt": {k: c1[k] for k in ("T_A_days", "M", "route", "marginal")},
                                  "primary": {k: c0[k] for k in ("T_A_days", "M", "route", "marginal")}})
        result["qr3_alternatives"][name] = {"options": {k: str(v) for k, v in kw.items()},
                                            "fits": tab["fits"],
                                            "n_entries_T_A_or_verdict_changed": len(diffs),
                                            "n_verdict_changes": sum(1 for x in diffs if x["changed"]),
                                            "differences": diffs}

json.dump(result, open(os.path.join(S, "analysis.json"), "w"), indent=1, default=str)
print("ok")

